/**
 * Validates that a Path parameter is not null.
 *
 * @param paramName the name of the parameter (for error messages)
 * @param paramValue the value to validate
 * @throws TikaConfigException if the value is null
 */
public static void mustNotBeEmpty(String paramName, Path paramValue) throws TikaConfigException {
    if (paramValue == null) {
        throw new TikaConfigException("parameter '" + paramName + "' must be set in the config file");
    }
}
